// Lambda pseudo-score
function score(rows) {
  let nulls = 0, total = 0;
  for (const r of rows) {
    total++;
    if (Object.values(r).some(v => v == null)) nulls++;
  }
  return Math.max(0, 100 - (nulls/total)*50);
}
